<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Expense Tracker</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: #f5f5f5;
            padding: 20px;
        }

        .container {
            max-width: 800px;
            margin: 0 auto;
            background: white;
            border-radius: 8px;
            padding: 30px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
        }

        h1 {
            margin-bottom: 30px;
            color: #333;
        }

        .form-section {
            margin-bottom: 30px;
            padding-bottom: 30px;
            border-bottom: 1px solid #e0e0e0;
        }

        .form-group {
            margin-bottom: 15px;
        }

        label {
            display: block;
            margin-bottom: 5px;
            color: #555;
            font-weight: 500;
        }

        input, select {
            width: 100%;
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 14px;
            font-family: inherit;
        }

        input:focus, select:focus {
            outline: none;
            border-color: #4CAF50;
            box-shadow: 0 0 4px rgba(76, 175, 80, 0.3);
        }

        button {
            padding: 10px 20px;
            background: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: 500;
            font-size: 14px;
        }

        button:hover {
            background: #45a049;
        }

        #form-error {
            color: #d32f2f;
            margin-top: 10px;
            font-size: 14px;
            min-height: 20px;
        }

        .filters-section {
            margin-bottom: 30px;
            padding: 20px;
            background: #f9f9f9;
            border-radius: 4px;
        }

        .filters-section h3 {
            margin-bottom: 15px;
            color: #333;
        }

        .filter-row {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 15px;
        }

        .summary-section {
            margin-bottom: 30px;
            padding: 20px;
            background: #f0f7ff;
            border-radius: 4px;
            border-left: 4px solid #2196F3;
        }

        .summary-section h3 {
            margin-bottom: 15px;
            color: #1976D2;
        }

        .summary-item {
            display: flex;
            justify-content: space-between;
            margin-bottom: 8px;
            padding: 5px 0;
        }

        .summary-item span:last-child {
            font-weight: 600;
        }

        .total-display {
            font-size: 24px;
            font-weight: bold;
            color: #2196F3;
            margin-top: 15px;
            padding-top: 15px;
            border-top: 1px solid #bbdefb;
        }

        .expenses-section {
            margin-top: 30px;
        }

        .expenses-section h3 {
            margin-bottom: 15px;
            color: #333;
        }

        .expense {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px;
            background: #f9f9f9;
            border-radius: 4px;
            margin-bottom: 10px;
            border-left: 4px solid #2196F3;
        }

        .expense-info {
            flex: 1;
        }

        .expense-amount {
            font-size: 18px;
            font-weight: bold;
            color: #2196F3;
        }

        .expense-details {
            display: flex;
            gap: 15px;
            margin-top: 5px;
            font-size: 13px;
            color: #666;
        }

        .expense-category {
            background: #e8f5e9;
            padding: 2px 8px;
            border-radius: 3px;
            font-weight: 500;
            color: #2e7d32;
        }

        .expense-note {
            font-style: italic;
            color: #999;
            margin-top: 5px;
        }

        .exp-del {
            padding: 8px 12px;
            background: #f44336;
            font-size: 12px;
            margin-left: 10px;
            flex-shrink: 0;
        }

        .exp-del:hover {
            background: #da190b;
        }

        .empty-state {
            text-align: center;
            color: #999;
            padding: 40px 20px;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Expense Tracker</h1>

        <div class="form-section">
            <h2>Add Expense</h2>
            <div class="form-group">
                <label for="amount">Amount ($)</label>
                <input type="number" id="amount" step="0.01" placeholder="0.00">
            </div>

            <div class="form-group">
                <label for="category">Category</label>
                <select id="category">
                    <option value="">-- Select Category --</option>
                    <option value="groceries">Groceries</option>
                    <option value="transport">Transport</option>
                    <option value="bills">Bills</option>
                    <option value="fun">Fun</option>
                </select>
            </div>

            <div class="form-group">
                <label for="date">Date</label>
                <input type="date" id="date">
            </div>

            <div class="form-group">
                <label for="note">Note (optional)</label>
                <input type="text" id="note" placeholder="Add a note...">
            </div>

            <button id="add-expense">Add Expense</button>
            <div id="form-error"></div>
        </div>

        <div class="filters-section">
            <h3>Filters</h3>
            <div class="filter-row">
                <div>
                    <label for="filter-category">Category</label>
                    <select id="filter-category">
                        <option value="all">All Categories</option>
                        <option value="groceries">Groceries</option>
                        <option value="transport">Transport</option>
                        <option value="bills">Bills</option>
                        <option value="fun">Fun</option>
                    </select>
                </div>
                <div>
                    <label for="filter-from">From Date</label>
                    <input type="date" id="filter-from">
                </div>
                <div>
                    <label for="filter-to">To Date</label>
                    <input type="date" id="filter-to">
                </div>
            </div>
        </div>

        <div class="summary-section">
            <h3>Summary</h3>
            <div id="category-totals"></div>
            <div class="total-display">Total: $<span id="total">0.00</span></div>
        </div>

        <div class="expenses-section">
            <h3>Expenses</h3>
            <div id="expense-list"></div>
            <div class="empty-state" id="empty-state">No expenses yet</div>
        </div>
    </div>

    <script>
        const STORAGE_KEY = 'expenses';
        const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

        let expenses = [];

        function loadExpenses() {
            const stored = localStorage.getItem(STORAGE_KEY);
            if (stored) {
                try {
                    expenses = JSON.parse(stored);
                } catch (e) {
                    expenses = [];
                }
            }
        }

        function saveExpenses() {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
        }

        function getVisibleExpenses() {
            const categoryFilter = document.getElementById('filter-category').value;
            const fromDate = document.getElementById('filter-from').value;
            const toDate = document.getElementById('filter-to').value;

            return expenses.filter(expense => {
                if (categoryFilter !== 'all' && expense.category !== categoryFilter) {
                    return false;
                }
                if (fromDate && expense.date < fromDate) {
                    return false;
                }
                if (toDate && expense.date > toDate) {
                    return false;
                }
                return true;
            });
        }

        function renderExpenses() {
            const list = document.getElementById('expense-list');
            const emptyState = document.getElementById('empty-state');
            const visibleExpenses = getVisibleExpenses();

            list.innerHTML = '';

            if (visibleExpenses.length === 0) {
                emptyState.style.display = 'block';
                updateTotals();
                return;
            }

            emptyState.style.display = 'none';

            const sorted = [...visibleExpenses].sort((a, b) => new Date(b.date) - new Date(a.date));

            sorted.forEach((expense) => {
                const expenseDiv = document.createElement('div');
                expenseDiv.className = 'expense';

                const date = new Date(expense.date);
                const formattedDate = date.toLocaleDateString('en-US', {
                    weekday: 'short',
                    year: 'numeric',
                    month: 'short',
                    day: 'numeric'
                });

                let noteHtml = '';
                if (expense.note) {
                    noteHtml = `<div class="expense-note">${escapeHtml(expense.note)}</div>`;
                }

                expenseDiv.innerHTML = `
                    <div class="expense-info">
                        <div class="expense-amount">$${Number(expense.amount).toFixed(2)}</div>
                        <div class="expense-details">
                            <span class="expense-category">${expense.category}</span>
                            <span>${formattedDate}</span>
                        </div>
                        ${noteHtml}
                    </div>
                    <button class="exp-del" data-id="${expense.id}">Delete</button>
                `;

                list.appendChild(expenseDiv);

                expenseDiv.querySelector('.exp-del').addEventListener('click', deleteExpense);
            });

            updateTotals();
        }

        function updateTotals() {
            const visibleExpenses = getVisibleExpenses();

            const total = visibleExpenses.reduce((sum, exp) => sum + Number(exp.amount), 0);
            document.getElementById('total').textContent = total.toFixed(2);

            const categoryTotals = {};
            CATEGORIES.forEach(cat => {
                categoryTotals[cat] = visibleExpenses
                    .filter(exp => exp.category === cat)
                    .reduce((sum, exp) => sum + Number(exp.amount), 0);
            });

            const categoryTotalsDiv = document.getElementById('category-totals');
            categoryTotalsDiv.innerHTML = '';

            CATEGORIES.forEach(cat => {
                const catDiv = document.createElement('div');
                catDiv.className = 'summary-item cat-total';
                catDiv.setAttribute('data-cat', cat);
                catDiv.innerHTML = `
                    <span>${cat.charAt(0).toUpperCase() + cat.slice(1)}</span>
                    <span>$${categoryTotals[cat].toFixed(2)}</span>
                `;
                categoryTotalsDiv.appendChild(catDiv);
            });
        }

        function addExpense(e) {
            e.preventDefault();

            const amount = document.getElementById('amount').value.trim();
            const category = document.getElementById('category').value;
            const date = document.getElementById('date').value;
            const note = document.getElementById('note').value.trim();
            const errorDiv = document.getElementById('form-error');

            errorDiv.textContent = '';

            if (!amount) {
                errorDiv.textContent = 'Amount is required';
                return;
            }

            const numAmount = Number(amount);
            if (isNaN(numAmount)) {
                errorDiv.textContent = 'Amount must be a valid number';
                return;
            }

            if (numAmount <= 0) {
                errorDiv.textContent = 'Amount must be greater than zero';
                return;
            }

            if (!category) {
                errorDiv.textContent = 'Category is required';
                return;
            }

            if (!date) {
                errorDiv.textContent = 'Date is required';
                return;
            }

            const expense = {
                id: Date.now(),
                amount: numAmount,
                category,
                date,
                note
            };

            expenses.push(expense);
            saveExpenses();

            document.getElementById('amount').value = '';
            document.getElementById('category').value = '';
            document.getElementById('date').value = '';
            document.getElementById('note').value = '';

            renderExpenses();
        }

        function deleteExpense(e) {
            const id = Number(e.target.getAttribute('data-id'));
            expenses = expenses.filter(exp => exp.id !== id);
            saveExpenses();
            renderExpenses();
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        document.getElementById('add-expense').addEventListener('click', addExpense);
        document.getElementById('filter-category').addEventListener('change', renderExpenses);
        document.getElementById('filter-from').addEventListener('change', renderExpenses);
        document.getElementById('filter-to').addEventListener('change', renderExpenses);

        loadExpenses();
        renderExpenses();
    </script>
</body>
</html>
